eval@spot:(async () => {
  const F = window.__tmtFluids;
  const s = window.__tmtGame.snapshot;
  const t = s.tanks[s.active].position;
  let best = 1e9, S = null;
  for (const p of F.shorePoints(6000, 'water')) { const d = Math.hypot(p[0] - t[0], p[1] - t[1], p[2] - t[2]); if (d < best) { best = d; S = p; } }
  const r0 = Math.hypot(...S);
  const u = S.map(v => v / r0);
  const a = Math.abs(u[1]) < 0.9 ? [0, 1, 0] : [1, 0, 0];
  const c1 = [u[1] * a[2] - u[2] * a[1], u[2] * a[0] - u[0] * a[2], u[0] * a[1] - u[1] * a[0]];
  const l1 = Math.hypot(...c1);
  const e1 = c1.map(v => v / l1);
  const e2 = [u[1] * e1[2] - u[2] * e1[1], u[2] * e1[0] - u[0] * e1[2], u[0] * e1[1] - u[1] * e1[0]];
  const at = (x, y) => { const d = [0, 1, 2].map(k => u[k] + (e1[k] * x + e2[k] * y) / r0); const l = Math.hypot(...d); return d.map(v => v / l * r0); };
  let seed = 11;
  const rand = () => { seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0; return seed / 4294967296; };
  for (let round = 0; round < 8; round++) {
    const cand = [];
    for (let i = 0; i < 64; i++) { const q = rand() * Math.PI * 2, d = 0.8 + rand() * 6; cand.push([Math.cos(q) * d, Math.sin(q) * d]); }
    const res = await F.probe(cand.map(([x, y]) => at(x, y)));
    for (let i = 0; i < res.length; i++) {
      if (res[i].water < 0.3) continue;
      const [cx, cy] = cand[i];
      for (let k = 0; k < 8; k++) {
        const q = k / 8 * Math.PI, dx = Math.cos(q), dy = Math.sin(q);
        const line = [];
        for (let j = -2; j <= 2; j++) line.push([cx + dx * j * 0.8, cy + dy * j * 0.8]);
        const w = await F.probe(line.map(([x, y]) => at(x, y)));
        if (w.every(z => z.water > 0.12)) {
          const level = res[i].surface;
          const lift = (p, h) => { const r = Math.hypot(...p); return p.map(v => v / r * (level + h)); };
          window.__spot = { from: lift(at(cx - dx * 2.6, cy - dy * 2.6), 0.1), to: lift(at(cx + dx * 2.6, cy + dy * 2.6), 0.1), mid: lift(at(cx, cy), 0), blast: lift(at(cx, cy), -0.25) };
          return JSON.stringify({ shoreDistance: +best.toFixed(2), centre: [cx, cy].map(v => +v.toFixed(2)), depths: w.map(z => +z.water.toFixed(2)) });
        }
      }
    }
  }
  return 'no spot';
})()
